import { useEffect, useState } from 'react'

export type InputType = 'touch' | 'mouse'

/**
 * Detects whether the user's primary input is touch or mouse, via the
 * `(hover: hover)` media query. Hybrid devices (touchscreen laptops) are
 * reported as `'mouse'` -- the query reflects the primary input method.
 *
 * Use this to swap wording like "Tap again" vs "Click again" in inline
 * confirmation buttons, or to toggle interaction patterns that differ
 * by input modality.
 *
 * Reactive: updates on the rare media-query change (e.g. a tablet
 * docked to a keyboard).
 */
export function useInputType(): InputType {
  const [type, setType] = useState<InputType>(() => {
    if (typeof window === 'undefined') return 'mouse'
    return window.matchMedia('(hover: hover)').matches ? 'mouse' : 'touch'
  })

  useEffect(() => {
    const mq = window.matchMedia('(hover: hover)')
    const handler = (e: MediaQueryListEvent) => setType(e.matches ? 'mouse' : 'touch')
    mq.addEventListener('change', handler)
    return () => mq.removeEventListener('change', handler)
  }, [])

  return type
}
